                <div style={{position:"relative",borderRadius:2,overflow:"hidden",border:"1px solid rgba(192,132,252,0.15)"}}>
                  <img className="bp-img" src={IMG_BLUEPRINT} alt="Nubi" style={{width:"100%",display:"block",maxHeight:225,objectFit:"cover",objectPosition:"top center"}} />
                  <div style={{position:"absolute",bottom:0,left:0,right:0,background:"rgba(10,5,20,0.78)",padding:"3px 6px"}}>
                    <div style={{fontSize:7,color:"rgba(192,132,252,0.55)",letterSpacing:2}}>NUBI // TECH SCHEMATIC</div>
                  </div>
                </div>
